lysogeny_contrasts_genes &lt;- create_contrasts_genes_table(
  group = "strains",
  filter = "Lysogeny"
)

lysogeny_genes_table &lt;- lysogeny_contrasts_genes$table
lysogeny_genes_status &lt;- lysogeny_contrasts_genes$status

status_order &lt;- match(
  lysogeny_genes_table$Gene_ID,
  lysogeny_genes_status$Gene_ID
)

if(anyNA(status_order)){
  stop(
    "Algunos Gene_ID de table no están presentes en status."
  )
}

lysogeny_genes_status &lt;- lysogeny_genes_status[
  status_order,
  ,
  drop = FALSE
]

stopifnot(
  identical(
    as.character(lysogeny_genes_table$Gene_ID),
    as.character(lysogeny_genes_status$Gene_ID)
  )
)

colnames(lysogeny_genes_table) &lt;- c(
  "Gene ID",
  "Gene symbol",
  "Description",
  "GIL01 vs GBJ002",
  "GIL16 vs GBJ002",
  "GIL16 vs GIL01"
)

status_aux &lt;- lysogeny_genes_status[
  ,
  -1,
  drop = FALSE
]

status_aux[] &lt;- lapply(
  status_aux,
  as.character
)

colnames(status_aux) &lt;- c(
  "Status GIL01 vs GBJ002",
  "Status GIL16 vs GBJ002",
  "Status GIL16 vs GIL01"
)

lfc_names &lt;- c(
  "GIL01 vs GBJ002",
  "GIL16 vs GBJ002",
  "GIL16 vs GIL01"
)

lysogeny_genes_table[lfc_names] &lt;- lapply(
  lysogeny_genes_table[lfc_names],
  as.numeric
)

lfc_matrix &lt;- as.matrix(
  lysogeny_genes_table[
    ,
    lfc_names,
    drop = FALSE
  ]
)

storage.mode(lfc_matrix) &lt;- "numeric"

status_matrix &lt;- as.matrix(status_aux)

de_mask &lt;- status_matrix %in% c(
  "UP",
  "DOWN"
)

de_values &lt;- abs(
  lfc_matrix[
    de_mask & !is.na(lfc_matrix)
  ]
)

if(length(de_values) == 0){

  max_abs &lt;- 1

} else {

  max_abs &lt;- ceiling(
    max(
      de_values,
      na.rm = TRUE
    )
  )

  if(!is.finite(max_abs) || max_abs &lt;= 0){
    max_abs &lt;- 1
  }
}

n_colors &lt;- 100

red_palette &lt;- grDevices::colorRampPalette(
  c(
    "#FFFFFF",
    "#F8696B"
  )
)(n_colors)

blue_palette &lt;- grDevices::colorRampPalette(
  c(
    "#FFFFFF",
    "#5A8AC6"
  )
)(n_colors)

get_cell_color &lt;- function(lfc, status){

  color &lt;- rep(
    "#FFFFFF",
    length(lfc)
  )

  valid &lt;- (
    !is.na(lfc) &
    !is.na(status) &
    status %in% c("UP", "DOWN")
  )

  if(!any(valid)){
    return(color)
  }

  intensity &lt;- abs(lfc[valid]) / max_abs

  intensity &lt;- pmax(
    0,
    pmin(
      1,
      intensity
    )
  )

  color_index &lt;- pmax(
    1,
    pmin(
      n_colors,
      ceiling(intensity * n_colors)
    )
  )

  valid_positions &lt;- which(valid)

  up_positions &lt;- valid_positions[
    status[valid] == "UP"
  ]

  down_positions &lt;- valid_positions[
    status[valid] == "DOWN"
  ]

  if(length(up_positions) &gt; 0){

    up_index &lt;- color_index[
      status[valid] == "UP"
    ]

    color[up_positions] &lt;- red_palette[
      up_index
    ]
  }

  if(length(down_positions) &gt; 0){

    down_index &lt;- color_index[
      status[valid] == "DOWN"
    ]

    color[down_positions] &lt;- blue_palette[
      down_index
    ]
  }

  color
}

color_aux &lt;- data.frame(
  `Color GIL01 vs GBJ002` = get_cell_color(
    lysogeny_genes_table[["GIL01 vs GBJ002"]],
    status_aux[["Status GIL01 vs GBJ002"]]
  ),
  `Color GIL16 vs GBJ002` = get_cell_color(
    lysogeny_genes_table[["GIL16 vs GBJ002"]],
    status_aux[["Status GIL16 vs GBJ002"]]
  ),
  `Color GIL16 vs GIL01` = get_cell_color(
    lysogeny_genes_table[["GIL16 vs GIL01"]],
    status_aux[["Status GIL16 vs GIL01"]]
  ),
  check.names = FALSE
)

lysogeny_genes_dt_data &lt;- cbind(
  lysogeny_genes_table,
  color_aux
)

all_colors &lt;- unique(
  c(
    "#FFFFFF",
    red_palette,
    blue_palette
  )
)

sketch &lt;- htmltools::withTags(
  table(
    class = "display",
    thead(
      tr(
        th(
          colspan = 3,
          style = "text-align: center; font-weight: bold;",
          "Gene annotation"
        ),
        th(
          colspan = 3,
          style = "text-align: center; font-weight: bold;",
          "Lysogeny contrasts"
        ),
        th(
          colspan = 3,
          style = "display:none;",
          ""
        )
      ),
      tr(
        lapply(
          colnames(lysogeny_genes_dt_data),
          function(x){
            th(
              style = if(
                grepl("^Color ", x)
              ) {
                "display:none;"
              } else {
                "text-align:center;"
              },
              x
            )
          }
        )
      )
    )
  )
)

lysogeny_genes_dt &lt;- DT::datatable(
  lysogeny_genes_dt_data,
  container = sketch,
  rownames = FALSE,
  filter = "top",
  extensions = c(
    "Buttons",
    "FixedColumns",
    "Scroller"
  ),
  options = list(
    dom = "Brftip",
    buttons = list(
      list(
        extend = "copy",
        exportOptions = list(
          columns = 0:5
        )
      ),
      list(
        extend = "csv",
        exportOptions = list(
          columns = 0:5
        )
      ),
      list(
        extend = "excel",
        exportOptions = list(
          columns = 0:5
        )
      )
    ),
    columnDefs = list(
      list(
        targets = 6:8,
        visible = FALSE,
        searchable = FALSE
      )
    ),
    fixedColumns = list(
      leftColumns = 1
    ),
    scrollX = TRUE,
    scrollY = 400,
    scroller = TRUE,
    deferRender = TRUE
  )
) %&gt;%
  DT::formatRound(
    columns = lfc_names,
    digits = 2
  ) %&gt;%
  DT::formatStyle(
    columns = "GIL01 vs GBJ002",
    valueColumns = "Color GIL01 vs GBJ002",
    backgroundColor = DT::styleEqual(
      all_colors,
      all_colors
    )
  ) %&gt;%
  DT::formatStyle(
    columns = "GIL16 vs GBJ002",
    valueColumns = "Color GIL16 vs GBJ002",
    backgroundColor = DT::styleEqual(
      all_colors,
      all_colors
    )
  ) %&gt;%
  DT::formatStyle(
    columns = "GIL16 vs GIL01",
    valueColumns = "Color GIL16 vs GIL01",
    backgroundColor = DT::styleEqual(
      all_colors,
      all_colors
    )
  ) %&gt;%
  DT::formatStyle(
    columns = c(
      "Gene ID",
      "Gene symbol",
      lfc_names
    ),
    `text-align` = "center"
  )

