    as.character(intra_genes_status$Gene_ID)
  )
)

colnames(intra_genes_table)[1:2] &lt;- c(
  "Gene ID",
  "Gene symbol"
)

status_aux &lt;- intra_genes_status[
  ,
  -1,
  drop = FALSE
]

status_aux[] &lt;- lapply(
  status_aux,
  as.character
)

lfc_names &lt;- colnames(
  intra_genes_table
)[4:ncol(intra_genes_table)]

colnames(status_aux) &lt;- paste0(
  "Status ",
  lfc_names
)

intra_genes_table[lfc_names] &lt;- lapply(
  intra_genes_table[lfc_names],
  as.numeric
)

lfc_matrix &lt;- as.matrix(
  intra_genes_table[
    ,
    lfc_names,
    drop = FALSE
  ]
)

storage.mode(lfc_matrix) &lt;- "numeric"

status_matrix &lt;- as.matrix(status_aux)

de_mask &lt;- status_matrix %in% c(
  "UP",
  "DOWN"
)

de_values &lt;- abs(
  lfc_matrix[
    de_mask & !is.na(lfc_matrix)
  ]
)

if(length(de_values) == 0){

  max_abs &lt;- 1

} else {

  max_abs &lt;- ceiling(
    max(
      de_values,
      na.rm = TRUE
    )
  )

  if(!is.finite(max_abs) || max_abs &lt;= 0){
    max_abs &lt;- 1
  }
}

n_colors &lt;- 100

red_palette &lt;- grDevices::colorRampPalette(
  c(
    "#FFFFFF",
    "#F8696B"
  )
)(n_colors)

blue_palette &lt;- grDevices::colorRampPalette(
  c(
    "#FFFFFF",
    "#5A8AC6"
  )
)(n_colors)

get_cell_color &lt;- function(lfc, status){

  color &lt;- rep(
    "#FFFFFF",
    length(lfc)
  )

  valid &lt;- (
    !is.na(lfc) &
    !is.na(status) &
    status %in% c("UP", "DOWN")
  )

  if(!any(valid)){
    return(color)
  }

  intensity &lt;- abs(lfc[valid]) / max_abs

  intensity &lt;- pmax(
    0,
    pmin(
      1,
      intensity
    )
  )

  color_index &lt;- pmax(
    1,
    pmin(
      n_colors,
      ceiling(intensity * n_colors)
    )
  )

  valid_positions &lt;- which(valid)

  up_positions &lt;- valid_positions[
    status[valid] == "UP"
  ]

  down_positions &lt;- valid_positions[
    status[valid] == "DOWN"
  ]

  if(length(up_positions) &gt; 0){

    up_index &lt;- color_index[
      status[valid] == "UP"
    ]

    color[up_positions] &lt;- red_palette[
      up_index
    ]
  }

  if(length(down_positions) &gt; 0){

    down_index &lt;- color_index[
      status[valid] == "DOWN"
    ]

    color[down_positions] &lt;- blue_palette[
      down_index
    ]
  }

  color
}

color_aux &lt;- as.data.frame(
  setNames(
    lapply(
      seq_along(lfc_names),
      function(i){

        get_cell_color(
          intra_genes_table[[lfc_names[i]]],
          status_aux[[i]]
        )
      }
    ),
    paste0(
      "Color ",
      lfc_names
    )
  ),
  check.names = FALSE
)

